    agents = pgTable(
      "agents",
      {
        id: uuid3("id").primaryKey().defaultRandom(),
        orgId: uuid3("org_id").notNull().references(() => organizations.id),
        name: text("name").notNull(),
        // e.g. 'Researcher', 'Writer', 'Engineer'
        role: text("role").notNull(),
        // e.g. 'market_researcher', 'content_writer', 'software_engineer'
        department: text("department"),
        // DEPRECATED — kept for backward compat. Use departmentId.
        departmentId: uuid3("department_id").references(() => departments.id),
        // primary department FK
        teamId: uuid3("team_id").references(() => teams.id),
        // primary team FK
        status: text("status").notNull().default("active"),
        // active | paused | archived
        // Per-agent autonomy level (F12) — configurable by the founder, enforced
        // SERVER-SIDE alongside the authority profile. observe | recommend | draft
        // | execute_with_approval | autonomous. A frontend toggle alone can never
        // authorize an action — enforcement reads this column in the execution path.
        autonomyLevel: text("autonomy_level").notNull().default("execute_with_approval"),
        weeklyCost: integer2("weekly_cost").notNull().default(0),
        // cost in cents
        tasksCompleted: integer2("tasks_completed").notNull().default(0),
        tasksFailed: integer2("tasks_failed").notNull().default(0),
        creditsUsed: integer2("credits_used").notNull().default(0),
        // total credits consumed
        currentTask: text("current_task"),
        // short description of what they're doing now
        capabilities: jsonb("capabilities").notNull().default([]),
        // array of capability strings
        config: jsonb("config").notNull().default({}),
        // agent-specific config
        // Explicit authority profile — defines what the agent CAN do, CAN spend, and what REQUIRES approval
        authority: jsonb("authority").notNull().default({
          canCreateTasks: true,
          canExecuteTasks: true,
          canAccessCompanyInfo: true,
          canCommunicateExternally: false,
          canModifyResources: false,
          spendingLimitCents: 0,
          // 0 = no spending allowed without approval
          requiresApprovalFor: ["financial_commitments", "external_communications", "irreversible_actions", "high_impact_decisions"],
          forbiddenActions: []
        }),
        lastActiveAt: timestamp("last_active_at", { withTimezone: true }),
        createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
        updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow()
      },
      (t) => [
        index("agents_org_idx").on(t.orgId),
        index("agents_status_idx").on(t.orgId, t.status),
        index("agents_dept_idx").on(t.departmentId)
      ]
    );
