    commandId,
    intent: {
      intent: command,
      category: "unknown",
      requiresApproval: false,
      riskLevel: "low",
      estimatedCost: 0,
      taskDecomposition: [],
      response: errorMessage
    },
    taskIds: [],
    status: "error",
    message: errorMessage,
    agentResults: [],
    creditsConsumed: 0,
    creditsRemaining: 0,
    llmProvider: "none",
    workflowTrace: finalizeTrace(trace, startTime)
