async function getRecentActivity(db, orgId, limit = 10) {
  const events = await db.select({
    id: activityEvents.id,
    type: activityEvents.type,
    summary: activityEvents.summary,
    reason: activityEvents.reason,
    cost: activityEvents.cost,
    occurredAt: activityEvents.occurredAt
  }).from(activityEvents).where(eq(activityEvents.orgId, orgId)).orderBy(desc(activityEvents.occurredAt)).limit(limit);
  return events;
}

