// src/routes/files.ts
function registerFileRoutes(app, deps) {
  const { db, config: config2, logger } = deps;
  app.get("/v1/files", async (request) => {
    const ctx = await requireAuth(request, deps);
    const url2 = new URL(request.url, "http://localhost");
    const limit = Math.min(parseInt(url2.searchParams.get("limit") ?? "50", 10), 200);
    const offset = Math.max(parseInt(url2.searchParams.get("offset") ?? "0", 10), 0);
    const [totalRow] = await db.select({ count: sql`count(*)::int` }).from(files).where(eq(files.orgId, ctx.orgId));
    const list = await listFiles2(db, ctx.orgId, { limit, offset });
    return { data: list, meta: { limit, offset, total: totalRow?.count ?? 0 } };
  });
  app.get("/v1/files/:id", async (request, reply) => {
    const ctx = await requireAuth(request, deps);
    const record2 = await getFileById(db, ctx.orgId, request.params.id);
    if (!record2) {
      reply.code(404);
      return { error: { code: "not_found", message: "File not found" } };
    }
    return { data: record2 };
  });
  app.get("/v1/files/:id/download", async (request, reply) => {
    const ctx = await requireAuth(request, deps);
    const result = await getFileUrl(config2, db, ctx.orgId, request.params.id);
    if (!result) {
      reply.code(404);
      return { error: { code: "not_found", message: "File not found" } };
    }
    return { data: { url: result.url, file: result.record } };
  });
  app.post("/v1/files", async (request, reply) => {
    const ctx = await requireAuth(request, deps);
    const uploadBody2 = external_exports.object({
      name: external_exports.string().min(1).max(255),
      mimeType: external_exports.string().min(1),
      body: external_exports.string(),
      // base64-encoded file content
      metadata: external_exports.record(external_exports.string(), external_exports.unknown()).optional(),
      agentId: external_exports.string().uuid().optional(),
      taskId: external_exports.string().uuid().optional()
    });
    const parsed = uploadBody2.safeParse(request.body);
    if (!parsed.success) throw validation(parsed.error.flatten());
    try {
      const buffer = Buffer.from(parsed.data.body, "base64");
      const result = await uploadFile(config2, db, ctx.orgId, {
        name: parsed.data.name,
        mimeType: parsed.data.mimeType,
        body: buffer,
        uploadedBy: ctx.userId,
        agentId: parsed.data.agentId,
        taskId: parsed.data.taskId,
        metadata: parsed.data.metadata
      });
      await appendAudit(db, {
        orgId: ctx.orgId,
        actorType: "user",
        actorId: ctx.userId,
        action: "file.uploaded",
        outcome: "success"
      });
      reply.code(201);
      return { data: result };
    } catch (err) {
      logger.error({ err, orgId: ctx.orgId }, "File upload failed");
      throw new Error("File upload failed");
    }
  });
  app.delete("/v1/files/:id", async (request, reply) => {
    const ctx = await requireAuth(request, deps);
    const deleted = await deleteFile(config2, db, ctx.orgId, request.params.id);
    if (!deleted) {
      reply.code(404);
      return { error: { code: "not_found", message: "File not found" } };
    }
    await appendAudit(db, {
      orgId: ctx.orgId,
      actorType: "user",
      actorId: ctx.userId,
      action: "file.deleted",
      outcome: "success"
    });
    reply.code(204);
    return reply.send();
  });
}

