// src/email/waitlist-drip.ts
var DUE_BATCH = 50;
async function enqueueDrip(db, signup, now = /* @__PURE__ */ new Date()) {
  const emails = dripEmailsFor({ name: signup.name, email: signup.email });
  const rows = emails.map((e) => ({
    signupId: signup.id,
    kind: e.kind,
    subject: e.subject,
    bodyText: e.bodyText,
    bodyHtml: e.bodyHtml,
    toEmail: signup.email,
    toName: signup.name,
    scheduledAt: new Date(now.getTime() + DRIP_DELAYS[e.kind])
  }));
  const inserted = await db.insert(waitlistEmails).values(rows);
  return inserted.rowCount ?? rows.length;
}
async function processDueWaitlistEmails(db, transport, now = /* @__PURE__ */ new Date()) {
  const due = await db.select().from(waitlistEmails).where(and(eq(waitlistEmails.status, "queued"), lte(waitlistEmails.scheduledAt, now))).orderBy(waitlistEmails.scheduledAt).limit(DUE_BATCH).for("update", { skipLocked: true });
  let sent = 0;
  let failed = 0;
  for (const row of due) {
    const result = await transport.send({
      to: row.toEmail,
      subject: row.subject,
      text: row.bodyText,
      html: row.bodyHtml
    });
    if (result.ok) {
      sent += 1;
      await db.update(waitlistEmails).set({ status: "sent", sentAt: now, attempts: row.attempts + 1, lastError: null }).where(eq(waitlistEmails.id, row.id));
    } else {
      failed += 1;
      await db.update(waitlistEmails).set({ status: "failed", attempts: row.attempts + 1, lastError: result.error ?? null }).where(eq(waitlistEmails.id, row.id));
    }
  }
  return { sent, failed };
}

// src/routes/waitlist.ts
function registerWaitlistRoutes(app, deps) {
  const { db } = deps;
  app.post("/v1/waitlist", async (request, reply) => {
    const parsed = waitlistBody.safeParse(request.body);
    if (!parsed.success) throw validation(parsed.error.flatten());
    const email3 = parsed.data.email.trim().toLowerCase();
    const [existing] = await db.select().from(waitlistSignups).where(eq(waitlistSignups.email, email3)).limit(1);
    if (existing) {
      reply.code(200);
      return { data: { email: email3, status: existing.status, already: true } };
    }
    const [row] = await db.insert(waitlistSignups).values({
      email: email3,
      name: parsed.data.name?.trim() || null,
      role: parsed.data.role ?? null,
      source: parsed.data.source ?? "landing"
    }).returning();
    if (!row) throw new Error("waitlist insert returned no row");
    try {
      await enqueueDrip(db, { id: row.id, email: row.email, name: row.name });
    } catch (err) {
      request.log.error({ err }, "failed to enqueue waitlist drip");
    }
    reply.code(201);
    return { data: { email: row.email, status: row.status, already: false } };
  });
  app.post("/v1/internal/waitlist/process-due", async (request, reply) => {
    if (!deps.config.INTERNAL_TOKEN) {
      reply.code(404);
      return { error: { code: "not_found", message: "Route not found" } };
    }
    const token = request.headers["x-internal-token"];
    if (typeof token !== "string" || token !== deps.config.INTERNAL_TOKEN) {
      reply.code(401);
      return { error: { code: "unauthorized", message: "Invalid internal token" } };
    }
    const transport = createEmailTransport(deps.config, deps.logger);
    const result = await processDueWaitlistEmails(db, transport);
    return { data: result };
  });
  app.get("/v1/waitlist/count", async () => {
    const [row] = await db.select({ n: count() }).from(waitlistSignups);
    return { data: { count: row?.n ?? 0 } };
  });
}

