function registerMemberRoutes(app, deps) {
  const { db } = deps;
  app.get("/v1/members", async (request) => {
    const ctx = await requireAuth(request, deps);
    const params = request.query;
    const limit = Math.min(Math.max(Number(params.limit) || 50, 1), 200);
    const offset = Math.max(Number(params.offset) || 0, 0);
    const search = params.search?.trim().toLowerCase() ?? "";
    const [totalRow] = await db.select({ count: sql`count(*)::int` }).from(memberships).where(eq(memberships.orgId, ctx.orgId));
    const memberList = await db.select({
      id: users.id,
      email: users.email,
      name: users.name,
      status: users.status,
      role: memberships.role,
      memberSince: memberships.createdAt,
      createdAt: users.createdAt
    }).from(memberships).innerJoin(users, eq(memberships.userId, users.id)).where(eq(memberships.orgId, ctx.orgId)).orderBy(desc(memberships.createdAt)).limit(limit).offset(offset);
    const filtered = search ? memberList.filter(
      (m) => m.name?.toLowerCase().includes(search) || m.email.toLowerCase().includes(search)
    ) : memberList;
    return {
      data: filtered.map((m) => ({
        id: m.id,
        name: m.name ?? "Unknown",
        email: m.email,
        role: m.role,
        type: "human",
        status: m.status,
        memberSince: m.memberSince,
        createdAt: m.createdAt
      })),
      meta: { limit, offset, total: totalRow?.count ?? 0 }
    };
  });
  app.get("/v1/members/all", async (request) => {
    const ctx = await requireAuth(request, deps);
    const params = request.query;
    const limit = Math.min(Math.max(Number(params.limit) || 50, 1), 200);
    const offset = Math.max(Number(params.offset) || 0, 0);
    const search = params.search?.trim().toLowerCase() ?? "";
    const humanMembers = await db.select({
      id: users.id,
      email: users.email,
      name: users.name,
      status: users.status,
      role: memberships.role,
      memberSince: memberships.createdAt,
      createdAt: users.createdAt
    }).from(memberships).innerJoin(users, eq(memberships.userId, users.id)).where(eq(memberships.orgId, ctx.orgId)).orderBy(desc(memberships.createdAt));
    const agentMembers = await db.select({
      id: agents.id,
      name: agents.name,
      role: agents.role,
      department: agents.department,
      status: agents.status,
      tasksCompleted: agents.tasksCompleted,
      weeklyCost: agents.weeklyCost,
      createdAt: agents.createdAt
    }).from(agents).where(eq(agents.orgId, ctx.orgId)).orderBy(desc(agents.createdAt));
    const allMembers = [
      ...humanMembers.map((m) => ({
        id: m.id,
        name: m.name ?? "Unknown",
        email: m.email,
        role: m.role,
        type: "human",
        status: m.status,
        department: null,
        tasksCompleted: 0,
        weeklyCost: 0,
        memberSince: m.memberSince,
        createdAt: m.createdAt
      })),
      ...agentMembers.map((a) => ({
        id: a.id,
        name: a.name,
        email: `${a.name.toLowerCase().replace(/[^a-z0-9]/g, ".")}@orq8.internal`,
        role: "agent",
        type: "agent",
        status: a.status,
        department: a.department,
        tasksCompleted: a.tasksCompleted,
        weeklyCost: a.weeklyCost,
        memberSince: a.createdAt,
        createdAt: a.createdAt
      }))
    ];
    const filtered = search ? allMembers.filter(
      (m) => m.name.toLowerCase().includes(search) || m.email.toLowerCase().includes(search)
    ) : allMembers;
    const total = filtered.length;
    const paginated = filtered.slice(offset, offset + limit);
    return {
      data: paginated,
      meta: { limit, offset, total }
    };
  });
}

