async function storeAgentMemory(db, opts) {
  const importance = opts.importance ?? 5;
  const tags = opts.tags ?? [];
  const tagPrefix = tags.length > 0 ? `[tags:${tags.join(",")}] ` : "";
  const [entry] = await db.insert(companyMemory).values({
    orgId: opts.orgId,
    agentId: opts.agentId,
    category: opts.category,
    content: `${tagPrefix}${opts.content}`,
    source: `agent_memory`,
    taskId: opts.taskId ?? null,
    importance: Math.min(10, Math.max(1, importance))
  }).returning();
  return entry?.id ?? null;
}
async function retrieveAgentMemory(db, opts) {
  const conditions = [
    eq(companyMemory.orgId, opts.orgId),
    eq(companyMemory.agentId, opts.agentId),
    eq(companyMemory.source, "agent_memory")
  ];
  if (opts.category) {
    conditions.push(eq(companyMemory.category, opts.category));
  }
  if (opts.minImportance) {
    conditions.push(sql`${companyMemory.importance} >= ${opts.minImportance}`);
  }
  if (opts.query) {
    conditions.push(
      or(
        ilike(companyMemory.content, `%${opts.query}%`)
      )
    );
  }
  const entries = await db.select().from(companyMemory).where(and(...conditions)).orderBy(desc(companyMemory.importance), desc(companyMemory.createdAt)).limit(opts.limit ?? 10);
  return entries.map((e) => {
    const tagMatch = e.content.match(/^\[tags:([^\]]+)\]\s*/);
    const tags = tagMatch ? tagMatch[1].split(",") : [];
    const cleanContent = tagMatch ? e.content.slice(tagMatch[0].length) : e.content;
    return {
      id: String(e.id),
      orgId: e.orgId,
      agentId: e.agentId ?? "",
      category: e.category ?? "context",
      content: cleanContent,
      importance: e.importance,
      taskIds: e.taskId ? [e.taskId] : [],
      tags,
      useCount: 0,
      lastUsedAt: null,
      createdAt: e.createdAt,
      updatedAt: e.updatedAt
    };
  });
}
async function getAgentMemoryStats(db, orgId, agentId) {
  const [totalResult] = await db.select({ count: sql`count(*)::int` }).from(companyMemory).where(and(
    eq(companyMemory.orgId, orgId),
    eq(companyMemory.agentId, agentId),
    eq(companyMemory.source, "agent_memory")
  ));
  const categoryRows = await db.select({
    category: companyMemory.category,
    count: sql`count(*)::int`
  }).from(companyMemory).where(and(
    eq(companyMemory.orgId, orgId),
    eq(companyMemory.agentId, agentId),
    eq(companyMemory.source, "agent_memory")
  )).groupBy(companyMemory.category);
  const [avgResult] = await db.select({ avg: sql`coalesce(avg(${companyMemory.importance}), 0)` }).from(companyMemory).where(and(
    eq(companyMemory.orgId, orgId),
    eq(companyMemory.agentId, agentId),
    eq(companyMemory.source, "agent_memory")
  ));
  const sevenDaysAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1e3);
  const [recentResult] = await db.select({ count: sql`count(*)::int` }).from(companyMemory).where(and(
    eq(companyMemory.orgId, orgId),
    eq(companyMemory.agentId, agentId),
    eq(companyMemory.source, "agent_memory"),
    sql`${companyMemory.createdAt} >= ${sevenDaysAgo}`
  ));
  const byCategory = {};
  for (const row of categoryRows) {
    byCategory[row.category] = row.count;
  }
  return {
    totalEntries: totalResult?.count ?? 0,
    byCategory,
    avgImportance: Number(avgResult?.avg ?? 0),
    recentEntries: recentResult?.count ?? 0
  };
}

