async function seedPlaybook(db, orgId, userId, slug, opts) {
  const playbook = getPlaybook(slug);
  if (!playbook) {
    throw new Error(`Unknown playbook: ${slug}`);
  }
  const marker = `playbook-seeded:${slug}`;
  const existingMarker = await db.select({ id: companyMemory.id }).from(companyMemory).where(and(eq(companyMemory.orgId, orgId), ilike(companyMemory.content, `%${marker}%`))).limit(1);
  if (existingMarker.length > 0) {
    return { slug, alreadySeeded: true, activation: null };
  }
  await upsertConstitution(db, orgId, playbook.constitution);
  let planToActivate = playbook.plan;
  let agentLimitApplied;
  if (opts?.enforceAgentLimit) {
    try {
      const { getCaps: getCaps2 } = await Promise.resolve().then(() => (init_entitlements(), entitlements_exports));
      const caps = await getCaps2(db, orgId);
      const fitted = fitPlanToAgentLimit(playbook.plan, caps.maxAgents);
      if (fitted.limitedTo < fitted.limitedFrom) {
        planToActivate = fitted.plan;
        agentLimitApplied = { from: fitted.limitedFrom, to: fitted.limitedTo };
      }
    } catch {
      agentLimitApplied = void 0;
    }
  }
  const activation = await activateCompany(db, orgId, userId, planToActivate);
  try {
    await ensureBuiltInCapabilities(db, orgId);
    for (const provider of ["github", "gmail", "linear"]) {
      await registerMcpServer(db, {
        orgId,
        name: `${provider} MCP`,
        description: `Model Context Protocol server exposing ${provider} through the ORQ8 connector (capability-checked, approval-gated, audited).`,
        provider
      });
    }
  } catch {
  }
  try {
    await createMemory(db, {
      orgId,
      category: "workflow",
      content: `[${marker}] Playbook seeded: ${slug} (${playbook.name}) \u2014 ${activation.departments.length} departments, ${activation.agents.length} AI employees, ${activation.goals.length} goals, ${activation.tasks.length} starter tasks${agentLimitApplied ? ` (workforce plan-limited from ${agentLimitApplied.from} to ${agentLimitApplied.to} AI employees by this plan \u2014 upgrade to unlock the full team)` : ""}.`,
      importance: 8,
      source: "playbooks:seed"
    });
  } catch {
  }
  try {
    await appendAudit(db, {
      orgId,
      actorType: "user",
      actorId: userId,
      action: "playbook.seeded",
      outcome: "success",
      resultRef: `${slug} \u2014 departments:${activation.departments.length};agents:${activation.agents.length};goals:${activation.goals.length};tasks:${activation.tasks.length}`
    });
  } catch {
  }
  return { slug, alreadySeeded: false, activation, agentLimitApplied };
}
async function upsertConstitution(db, orgId, constitution) {
  const [org] = await db.select({ settings: organizations.settings }).from(organizations).where(eq(organizations.id, orgId)).limit(1);
  if (!org) return;
  const settings = org.settings ?? {};
  const current = settings.constitution ?? {};
  const merged = {
    ...current,
    ...constitution,
    agentPolicies: { ...current.agentPolicies ?? {}, ...constitution.agentPolicies },
    budgetPolicy: { ...current.budgetPolicy ?? {}, ...constitution.budgetPolicy },
    version: Number(current.version ?? 0) + 1,
    updatedAt: (/* @__PURE__ */ new Date()).toISOString()
  };
  await db.update(organizations).set({ settings: { ...settings, constitution: merged } }).where(eq(organizations.id, orgId));
}

