function registerCompanyHealthRoutes(app, deps) {
  const { db } = deps;
  app.get("/v1/health", async (request) => {
    const ctx = await requireAuth(request, deps);
    const health = await getCompanyHealth(db, ctx.orgId);
    return { data: health };
  });
}

