async function createSquad(db, orgId, userId, data) {
  if (data.agentIds.length > 0) {
    const rows = await db.select({ id: agents.id }).from(agents).where(and(eq(agents.orgId, orgId), inArray(agents.id, data.agentIds)));
    const validIds = new Set(rows.map((r) => r.id));
    const invalid = data.agentIds.find((id) => !validIds.has(id));
    if (invalid) throw new Error(`Agent ${invalid} does not belong to this organization`);
  }
  const [squad] = await db.insert(squads).values({
    orgId,
    name: data.name.trim(),
    purpose: data.purpose?.trim() || null,
    objective: data.objective.trim(),
    status: "active",
    createdBy: userId
  }).returning();
  if (!squad) throw new Error("createSquad returned no row");
  if (data.agentIds.length > 0) {
    await db.insert(squadAgents).values(data.agentIds.map((agentId) => ({ orgId, squadId: squad.id, agentId }))).onConflictDoNothing();
  }
  return getSquad(db, orgId, squad.id);
}
async function listSquads(db, orgId) {
  const rows = await db.select().from(squads).where(and(eq(squads.orgId, orgId), sql`${squads.status} <> 'archived'`)).orderBy(desc(squads.updatedAt)).limit(100);
  const memberships2 = await db.select({
    squadId: squadAgents.squadId,
    id: agents.id,
    name: agents.name,
    role: agents.role,
    status: agents.status
  }).from(squadAgents).innerJoin(agents, eq(agents.id, squadAgents.agentId)).where(eq(squadAgents.orgId, orgId));
  const bySquad = /* @__PURE__ */ new Map();
  for (const m of memberships2) {
    const list = bySquad.get(m.squadId) ?? [];
    list.push({ id: m.id, name: m.name, role: m.role, status: m.status });
    bySquad.set(m.squadId, list);
  }
  return rows.map((r) => ({ ...r, agents: bySquad.get(r.id) ?? [] }));
}
async function getSquad(db, orgId, id) {
  const [squad] = await db.select().from(squads).where(and(eq(squads.id, id), eq(squads.orgId, orgId))).limit(1);
  if (!squad) return null;
  const memberships2 = await db.select({ id: agents.id, name: agents.name, role: agents.role, status: agents.status }).from(squadAgents).innerJoin(agents, eq(agents.id, squadAgents.agentId)).where(and(eq(squadAgents.orgId, orgId), eq(squadAgents.squadId, id)));
  return { ...squad, agents: memberships2 };
}
async function updateSquadStatus(db, orgId, id, status) {
  const rows = await db.update(squads).set({ status, updatedAt: /* @__PURE__ */ new Date() }).where(and(eq(squads.id, id), eq(squads.orgId, orgId))).returning();
  return rows[0];
}
async function startSquad(db, orgId, userId, squadId, tasksInput) {
  const squad = await getSquad(db, orgId, squadId);
  if (!squad) throw new Error("Squad not found");
  const plan = await createDelegationPlan(db, orgId, tasksInput);
  const result = await executeDelegationPlan(db, orgId, plan, tasksInput);
  const parentTaskId = result.createdTaskIds[0] ?? null;
  await db.update(squads).set({ parentTaskId, updatedAt: /* @__PURE__ */ new Date() }).where(eq(squads.id, squadId));
  if (result.createdTaskIds.length > 0) {
    await db.update(tasks).set({ squadId }).where(and(eq(tasks.orgId, orgId), inArray(tasks.id, result.createdTaskIds)));
  }
  await appendAudit(db, {
    orgId,
    actorType: "user",
    actorId: userId,
    action: "squad.started",
    outcome: "success",
    resultRef: `${squad.name} \u2014 ${result.createdTaskIds.length} tasks delegated`
  });
  const fresh = await getSquad(db, orgId, squadId);
  return { squad: fresh, createdTaskIds: result.createdTaskIds, parentTaskId };
}
async function monitorSquad(db, orgId, squadId) {
  const squad = await getSquad(db, orgId, squadId);
  if (!squad) return null;
  const squadTasks = await db.select({
    id: tasks.id,
    title: tasks.title,
    status: tasks.status,
    priority: tasks.priority,
    agentId: tasks.agentId,
    cost: tasks.cost,
    updatedAt: tasks.updatedAt
  }).from(tasks).where(and(eq(tasks.orgId, orgId), eq(tasks.squadId, squadId)));
  const agentIds = [...new Set(squadTasks.map((t) => t.agentId).filter((id) => Boolean(id)))];
  const agentRows = agentIds.length ? await db.select({ id: agents.id, name: agents.name }).from(agents).where(and(eq(agents.orgId, orgId), inArray(agents.id, agentIds))) : [];
  const nameById = new Map(agentRows.map((a) => [a.id, a.name]));
  const completed = squadTasks.filter((t) => t.status === "completed").length;
  const inProgress = squadTasks.filter((t) => t.status === "in_progress").length;
  const pending = squadTasks.filter((t) => t.status === "pending").length;
  const failed = squadTasks.filter((t) => t.status === "failed").length;
  const totalCost = squadTasks.reduce((s, t) => s + t.cost, 0);
  return {
    squad,
    tasks: squadTasks.map((t) => ({
      id: t.id,
      title: t.title,
      status: t.status,
      priority: t.priority,
      agentId: t.agentId,
      agentName: t.agentId && nameById.has(t.agentId) ? nameById.get(t.agentId) ?? null : null,
      cost: t.cost,
      updatedAt: t.updatedAt.toISOString()
    })),
    summary: {
      totalTasks: squadTasks.length,
      completed,
      inProgress,
      pending,
      failed,
      totalCost,
      completionRate: squadTasks.length > 0 ? Math.round(completed / squadTasks.length * 100) : 0
    }
  };
}

