async function getHourlyRate(db, orgId) {
  const [org] = await db.select({ settings: organizations.settings }).from(organizations).where(eq(organizations.id, orgId));
  const settings = org?.settings ?? {};
  const roi = settings.roi;
  return {
    hourlyRate: typeof roi?.hourlyRate === "number" ? roi.hourlyRate : 75,
    currency: "USD"
  };
}
async function setHourlyRate(db, orgId, hourlyRate) {
  const [org] = await db.select({ settings: organizations.settings }).from(organizations).where(eq(organizations.id, orgId));
  const settings = org?.settings ?? {};
  settings.roi = { ...settings.roi ?? {}, hourlyRate };
  await db.update(organizations).set({ settings }).where(eq(organizations.id, orgId));
}

